from datetime import date, timedelta
import calendar

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    sy, sm, sd = (int(p) for p in start.split("-"))
    s = date(sy, sm, sd)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = s
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        wanted = { _WD[code] for code in parts[2].split(",") }
        monday0 = s - timedelta(days=s.weekday())
        w = 0
        while len(out) < count:
            week_monday = monday0 + timedelta(weeks=w)
            for offset in range(7):
                if offset not in wanted:
                    continue
                dt = week_monday + timedelta(days=offset)
                if dt >= s:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        break
            w += k
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        day_n = int(parts[2])
        idx = 0
        while len(out) < count:
            yy = sy + (sm - 1 + idx) // 12
            mm = (sm - 1 + idx) % 12 + 1
            dim = calendar.monthrange(yy, mm)[1]
            if day_n == -1:
                dt = date(yy, mm, dim)
            elif day_n <= dim:
                dt = date(yy, mm, day_n)
            else:
                dt = None
            if dt is not None and dt >= s:
                out.append(dt.isoformat())
            idx += k
        return out

    if kind == "MONTHLY":
        nth = int(parts[2])
        wd = _WD[parts[3]]
        idx = 0
        while len(out) < count:
            yy = sy + (sm - 1 + idx) // 12
            mm = (sm - 1 + idx) % 12 + 1
            dim = calendar.monthrange(yy, mm)[1]
            if nth == -1:
                last = date(yy, mm, dim)
                dt = last - timedelta(days=(last.weekday() - wd) % 7)
            else:
                first = date(yy, mm, 1)
                day = 1 + (wd - first.weekday()) % 7 + (nth - 1) * 7
                dt = date(yy, mm, day) if day <= dim else None
            if dt is not None and dt >= s:
                out.append(dt.isoformat())
            idx += k
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    yi = 0
    while len(out) < count:
        yy = sy + yi
        try:
            dt = date(yy, mm, dd)
        except ValueError:
            dt = None
        if dt is not None and dt >= s:
            out.append(dt.isoformat())
        yi += k
    return out
